        return value == null ? null : LogLevelMsg.values[value];
      case 132:
        final value = readValue(buffer) as int?;
        return value == null ? null : ThemeModeMsg.values[value];
      case 133:
        final value = readValue(buffer) as int?;
        return value == null ? null : AuthModeMsg.values[value];
      case 134:
        final value = readValue(buffer) as int?;
        return value == null ? null : SecondFactorMsg.values[value];
      case 135:
        final value = readValue(buffer) as int?;
        return value == null ? null : ConnectResultMsg.values[value];
      case 136:
        final value = readValue(buffer) as int?;
        return value == null ? null : LogEventMsg.values[value];
      case 137:
        return EmailOtpMsg.decode(readValue(buffer)!);
      case 138:
        return ProfileMsg.decode(readValue(buffer)!);
      case 139:
        return ProbeResultMsg.decode(readValue(buffer)!);
      case 140:
        return PrefsMsg.decode(readValue(buffer)!);
      case 141:
        return VpnStatusMsg.decode(readValue(buffer)!);
      case 142:
        return LogEntryMsg.decode(readValue(buffer)!);
      default:
        return super.readValueOfType(type, buffer);
    }
  }
}

